type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate  decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"               // PIC X len=1 = "N"
var WsIdx int64 = 0                      // PIC 9 len=1 = 0
var WsTier int64 = 0                     // PIC 9 len=1 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)  // PIC 9(6)V99 len=8 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                    // PIC 9(3) len=3 = 0
var WsSalesEd string // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string  // PIC 9.99 len=4
var WsCommEd string  // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14

// tier tables 1-based
var tierLimits [5]decimal.Decimal
var tierRates [5]decimal.Decimal

var salesRec SalesRec
var salesFileLines []string
var salesFileIdx int
var inputDone bool

func formatEdited(pic string, val decimal.Decimal) string {
	// val is non-negative in this program; handle sign generically
	isNeg := val.IsNegative()
	if isNeg {
		val = val.Neg()
	}
	// count digit placeholders before and after dot
	dotPos := strings.Index(pic, ".")
	var intPicPart, decPicPart string
	if dotPos >= 0 {
		intPicPart = pic[:dotPos]
		decPicPart = pic[dotPos+1:]
	} else {
		intPicPart = pic
		decPicPart = ""
	}
	intSlots := 0
	intPicChars := []rune{} // only 'Z'/'9' in order for integer part
	for _, c := range intPicPart {
		if c == 'Z' || c == '9' {
			intSlots++
			intPicChars = append(intPicChars, c)
		}
	}
	decSlots := 0
	for _, c := range decPicPart {
		if c == 'Z' || c == '9' {
			decSlots++
		}
	}

	// integer part and fractional part
	intPart := val.Truncate(0).Abs()
	// fractional part as integer 0..10^decSlots-1 with rounding already applied (val scale matches)
	fracPart := val.Abs().Sub(intPart)

	// Build integer digits string of length intSlots (overflow truncation)
	// Get integer part as decimal string without exponent
	intStr := intPart.StringFixed(0) // no decimal
	// Remove possible sign
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// intStr may be "0"
	// Pad / truncate to intSlots keeping low-order digits
	var intDigits string
	if len(intStr) > intSlots {
		intDigits = intStr[len(intStr)-intSlots:]
	} else {
		intDigits = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}

	// Build decimal digits
	var decDigits string
	if decSlots > 0 {
		// Shift fracPart
		mult := decimal.New(1, int32(decSlots)) // 10^decSlots
		fracInt := fracPart.Mul(mult).Truncate(0)
		// due to exact binary decimal, should be exact
		fracStr := fracInt.StringFixed(0)
		if len(fracStr) > decSlots {
			fracStr = fracStr[len(fracStr)-decSlots:]
		} else if len(fracStr) < decSlots {
			fracStr = strings.Repeat("0", decSlots-len(fracStr)) + fracStr
		}
		decDigits = fracStr
	}

	// Determine suppression for integer digit slots
	firstNonZero := -1
	for i, ch := range intDigits {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zero: keep last digit as zero
		firstNonZero = intSlots - 1
	}
	suppressed := make([]bool, intSlots)
	for i := 0; i < intSlots; i++ {
		if i < firstNonZero && intPicChars[i] == 'Z' {
			suppressed[i] = true
		} else {
			suppressed[i] = false
		}
	}

	// Build output by walking pic
	var out strings.Builder
	intDigitIdx := 0
	decDigitIdx := 0
	// For comma suppression: need to know if all digit slots to the left are suppressed
	// We can determine for each comma position: if every integer digit slot before it is suppressed, then space
	for _, c := range pic {
		switch c {
		case 'Z', '9':
			isSup := suppressed[intDigitIdx]
			if isSup {
				out.WriteRune(' ')
			} else {
				out.WriteRune(rune(intDigits[intDigitIdx]))
			}
			intDigitIdx++
		case ',':
			// check if all int digits to the left of this comma are suppressed
			// number of int digits already emitted = intDigitIdx
			allSup := true
			if intDigitIdx == 0 {
				allSup = true
			} else {
				for k := 0; k < intDigitIdx; k++ {
					if !suppressed[k] {
						allSup = false
						break
					}
				}
			}
			// Also if remaining? spec says commas inside suppressed zone become spaces
			if allSup {
				out.WriteRune(' ')
			} else {
				out.WriteRune(',')
			}
		case '.':
			out.WriteRune('.')
		default:
			out.WriteRune(c)
		}
		// handle decimal digits after dot: they are '9's in pic, but we already handle '9' case
		// Actually decimal part placeholders are also '9's and we consume decDigits
		// The above case for '9' currently consumes intDigits; need separate handling for dec part
		// To distinguish, we use dotPos: before dot consume intDigits, after dot consume decDigits
		// So we need to track whether we are past dot
		_ = decDigitIdx
	}
	// The above loop incorrectly consumed intDigits for decimal part.
	// Fix: redo with state pastDot
	// Rebuild correctly:
	out.Reset()
	intDigitIdx = 0
	decDigitIdx = 0
	pastDot := false
	for _, c := range pic {
		if c == '.' {
			out.WriteRune('.')
			pastDot = true
			continue
		}
		if c == ',' {
			allSup := true
			if intDigitIdx == 0 {
				allSup = true
			} else {
				for k := 0; k < intDigitIdx; k++ {
					if !suppressed[k] {
						allSup = false
						break
					}
				}
			}
			// commas only appear before dot in these pics
			if allSup {
				out.WriteRune(' ')
			} else {
				out.WriteRune(',')
			}
			continue
		}
		if c == 'Z' || c == '9' {
			if !pastDot {
				isSup := suppressed[intDigitIdx]
				if isSup {
					out.WriteRune(' ')
				} else {
					out.WriteRune(rune(intDigits[intDigitIdx]))
				}
				intDigitIdx++
			} else {
				// decimal part, always digit
				if decDigitIdx < len(decDigits) {
					out.WriteRune(rune(decDigits[decDigitIdx]))
				} else {
					out.WriteRune('0')
				}
				decDigitIdx++
			}
		} else {
			out.WriteRune(c)
		}
	}
	res := out.String()
	// handle negative (not needed here)
	if isNeg {
		// COBOL would show sign; not required
	}
	return res
}

func formatUneditedInt(val int64, digits int) string {
	s := fmt.Sprintf("%d", val)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func parseSalesRec(line string) SalesRec {
	// pad to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	id := line[0:4]
	salesStr := line[4:12]
	salesStr = strings.TrimSpace(salesStr)
	var d decimal.Decimal
	if salesStr == "" {
		d = decimal.NewFromInt(0)
	} else {
		// digits only, implied 2 decimals
		// may contain spaces? trim already
		// parse as integer
		// ensure digits
		clean := ""
		for _, ch := range salesStr {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			} else if ch == '-' {
				clean += string(ch)
			}
		}
		if clean == "" || clean == "-" {
			d = decimal.NewFromInt(0)
		} else {
			neg := false
			if clean[0] == '-' {
				neg = true
				clean = clean[1:]
			}
			// remove leading zeros for NewFromString
			bi, _ := decimal.NewFromString(clean)
			d = decimal.New(bi.IntPart(), -2)
			if neg {
				d = d.Neg()
			}
		}
	}
	// Truncate to 9(6)V99 semantics (store low-order truncation is handled later, keep as is)
	return SalesRec{SrId: id, SrSales: d}
}

func INITPARA() {
	tierLimits[1] = decimal.NewFromFloat(1000.00)
	tierRates[1] = decimal.NewFromFloat(2.50)
	tierLimits[2] = decimal.NewFromFloat(5000.00)
	tierRates[2] = decimal.NewFromFloat(4.00)
	tierLimits[3] = decimal.NewFromFloat(20000.00)
	tierRates[3] = decimal.NewFromFloat(5.50)
	tierLimits[4] = decimal.NewFromFloat(999999.99)
	tierRates[4] = decimal.NewFromFloat(7.25)
	// Ensure exact scales: use string
	tierLimits[1] = decimal.RequireFromString("1000.00")
	tierLimits[2] = decimal.RequireFromString("5000.00")
	tierLimits[3] = decimal.RequireFromString("20000.00")
	tierLimits[4] = decimal.RequireFromString("999999.99")
	tierRates[1] = decimal.RequireFromString("2.50")
	tierRates[2] = decimal.RequireFromString("4.00")
	tierRates[3] = decimal.RequireFromString("5.50")
	tierRates[4] = decimal.RequireFromString("7.25")
}

func READPARA() {
	if salesFileIdx >= len(salesFileLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := salesFileLines[salesFileIdx]
	salesFileIdx++
	salesRec = parseSalesRec(line)
}

func PROCESSPARA() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if salesRec.SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) / 100
	rate := tierRates[WsTier]
	comp := salesRec.SrSales.Mul(rate).Shift(-2)
	compRounded := comp.Round(2)
	// store with overflow truncation (low-order digits) and scale 2
	// PIC 9(6)V99: 6 integer digits max, 2 decimals
	// Implement truncation of high-order integer digits if overflow
	// For this dataset overflow unlikely, but implement
	WsComm = storePic9V99(compRounded, 6, 2)

	WsTotal = WsTotal.Add(WsComm)
	// WsTotal PIC 9(9)V99 may overflow similarly; keep full but store logic
	// For total accumulation, COBOL would truncate high-order on each ADD? ADD ... TO keeps low-order? spec says storing keeps low-order.
	// We'll apply store after each add to mimic
	WsTotal = storePic9V99(WsTotal, 9, 2)

	WsCount++

	WsSalesEd = formatEdited("ZZZ,ZZ9.99", salesRec.SrSales)
	WsRateEd = formatEdited("9.99", rate)
	WsCommEd = formatEdited("ZZZ,ZZ9.99", WsComm)

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	tierStr := formatUneditedInt(WsTier, 1)
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)

	READPARA()
}

func storePic9V99(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate/round already done; now enforce high-order digit drop if integer part exceeds intDigits
	// Keep sign
	isNeg := val.IsNegative()
	absVal := val.Abs()
	intPart := absVal.Truncate(0)
	fracPart := absVal.Sub(intPart)
	// modulo 10^intDigits for integer part
	mod := decimal.New(1, int32(intDigits)) // 10^intDigits
	// intPart mod
	// Use DivMod
	// intPart is within int64 range for these sizes (9 digits) so can use IntPart
	// Use decimal Mod via: intPart - (intPart.Div(mod).Truncate(0).Mul(mod))
	q := intPart.Div(mod).Truncate(0)
	newInt := intPart.Sub(q.Mul(mod))
	newVal := newInt.Add(fracPart)
	if isNeg {
		newVal = newVal.Neg()
	}
	// ensure scale
	newVal = newVal.Truncate(scale)
	return newVal
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsTotal)
	countStr := formatUneditedInt(WsCount, 3)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	INITPARA()
	// OPEN INPUT SALES-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		salesFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// scanner strips \r and \n, but we need raw bytes; spaces are preserved
			salesFileLines = append(salesFileLines, line)
		}
		f.Close()
	}
	salesFileIdx = 0
	inputDone = false
	WsEofFlag = "N"
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	// CLOSE
	SUMMARYPARA()
}

